typedef enum {
    LDACBT_SMPL_FMT_S16 = 0x2,
    LDACBT_SMPL_FMT_S24 = 0x3,
    LDACBT_SMPL_FMT_S32 = 0x4,
    LDACBT_SMPL_FMT_F32 = 0x5,
} LDACBT_SMPL_FMT_T;

