// Allocate a new LDAC encoder handle and wrap it into an object the runtime can track
HANDLE_LDAC_BT raw = ldacBT_get_handle();
if (!raw) { FUZZ_BAIL(); }
// Wrap the raw handle (HANDLE_LDAC_BT) into a managed object pointer (HANDLE_LDAC_BT *)
HANDLE_LDAC_BT *hLdacBt = new HANDLE_LDAC_BT;
*hLdacBt = raw;

// Newly created handle is not yet initialized for encoding
FUZZ_SET_ATTR_INT(hLdacBt, "freed", 0);
FUZZ_SET_ATTR_INT(hLdacBt, "init", 0);
FUZZ_SET_ATTR_INT(hLdacBt, "eqmid", -1);
FUZZ_SET_ATTR_INT(hLdacBt, "mtu", 0);
FUZZ_SET_ATTR_INT(hLdacBt, "cm", 0);
FUZZ_SET_ATTR_INT(hLdacBt, "sf", 0);
FUZZ_SET_ATTR_INT(hLdacBt, "fmt", 0);
FUZZ_SET_ATTR_INT(hLdacBt, "channels", 0);

// Enforce that this is a valid, not-yet-freed handle
if (!hLdacBt) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(hLdacBt, "freed")) { FUZZ_BAIL(); }

// Free underlying resources
ldacBT_free_handle(*hLdacBt);

// Mark as freed to prevent future use if accidentally retained
FUZZ_SET_ATTR_INT(hLdacBt, "freed", 1);
// Drop the object by not returning it as an output (runtime should not reuse it)

// Closing requires a valid, initialized handle
if (!hLdacBt) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(hLdacBt, "freed")) { FUZZ_BAIL(); }
int init = FUZZ_GET_ATTR_INT(hLdacBt, "init");
if (!init) { FUZZ_BAIL(); }

// Close encoder state but keep handle reusable
ldacBT_close_handle(*hLdacBt);

// Update state: no longer initialized
FUZZ_SET_ATTR_INT(hLdacBt, "init", 0);
// Keep other metadata for potential re-init

// Simple version query; no inputs/outputs required
int ver = ldacBT_get_version();
// Basic property: version is a non-negative integer (library-defined encoding)
FUZZ_ASSERT(ver >= 0, "Version must be non-negative");

// Requires an initialized handle
if (!hLdacBt) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(hLdacBt, "freed")) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(hLdacBt, "init")) { FUZZ_BAIL(); }

int sf = ldacBT_get_sampling_freq(*hLdacBt);
// On success, should be one of supported values; we accept -1 as failure per API
if (sf != -1) {
    // If we have stored sf attribute, it should match
    int sf_attr = FUZZ_GET_ATTR_INT(hLdacBt, "sf");
    if (sf_attr != 0) {
        FUZZ_ASSERT(sf == sf_attr, "Reported sampling frequency must match initialized value");
    }
}

// Requires an initialized handle
if (!hLdacBt) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(hLdacBt, "freed")) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(hLdacBt, "init")) { FUZZ_BAIL(); }

int br = ldacBT_get_bitrate(*hLdacBt);
// Accept -1 as failure; otherwise positive
if (br != -1) { FUZZ_ASSERT(br > 0, "Bitrate must be positive when returned"); }

// Validate handle
if (!hLdacBt) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(hLdacBt, "freed")) { FUZZ_BAIL(); }

// Parameters: constrain per API
int mtu = (int)(*FUZZ_PARAM(unsigned int) % 901u) + 100; // [100, 1000]
int cm = (int)(*FUZZ_PARAM(unsigned int) % 3u);           // choose among 0,1,2 (implementation-defined channel modes)
// Choose EQMID within a small valid range
int eqmid = (int)(*FUZZ_PARAM(unsigned int) % 5u);        // 0..4 plausible range incl. ABR

// fmt: choose one of the supported enum values. We use fmtIn when provided by runtime; else pick from known set
LDACBT_SMPL_FMT_T fmt = LDACBT_SMPL_FMT_S16;
int fmtChoice = (int)(*FUZZ_PARAM(unsigned int) % 4u);
if (fmtChoice == 0) fmt = LDACBT_SMPL_FMT_S16;
else if (fmtChoice == 1) fmt = LDACBT_SMPL_FMT_S24;
else if (fmtChoice == 2) fmt = LDACBT_SMPL_FMT_S32;
else fmt = LDACBT_SMPL_FMT_F32;
// Overwrite with provided fmtIn if non-null to increase cross-stub coherence
if (fmtIn) { fmt = *fmtIn; }

// Supported sampling frequencies set
int sf_set[4] = {44100, 48000, 88200, 96000};
int sf = sf_set[*FUZZ_PARAM(unsigned int) % 4u];

int rc = ldacBT_init_handle_encode(*hLdacBt, mtu, eqmid, cm, fmt, sf);
if (rc != 0) { FUZZ_BAIL(); }

// Track encoder state and parameters
FUZZ_SET_ATTR_INT(hLdacBt, "init", 1);
FUZZ_SET_ATTR_INT(hLdacBt, "mtu", mtu);
FUZZ_SET_ATTR_INT(hLdacBt, "cm", cm);
FUZZ_SET_ATTR_INT(hLdacBt, "eqmid", eqmid);
FUZZ_SET_ATTR_INT(hLdacBt, "sf", sf);
FUZZ_SET_ATTR_INT(hLdacBt, "fmt", (int)fmt);
// Derive an assumed channel count for buffer sizing (best-effort; actual cm mapping is implementation-defined)
int channels = (cm == 0) ? 2 : 2; // default to stereo to satisfy interleaved buffer expectations
FUZZ_SET_ATTR_INT(hLdacBt, "channels", channels);

// Requires initialized handle
if (!hLdacBt) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(hLdacBt, "freed")) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(hLdacBt, "init")) { FUZZ_BAIL(); }

int eqmid = (int)(*FUZZ_PARAM(unsigned int) % 5u); // plausible 0..4
int rc = ldacBT_set_eqmid(*hLdacBt, eqmid);
if (rc != 0) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(hLdacBt, "eqmid", eqmid);

// Requires initialized handle
if (!hLdacBt) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(hLdacBt, "freed")) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(hLdacBt, "init")) { FUZZ_BAIL(); }

int eq = ldacBT_get_eqmid(*hLdacBt);
if (eq != -1) {
    // if we have an attribute recorded, check it
    int eq_attr = FUZZ_GET_ATTR_INT(hLdacBt, "eqmid");
    if (eq_attr >= 0) { FUZZ_ASSERT(eq == eq_attr, "EQMID should match previously set value"); }
}

// Requires initialized handle
if (!hLdacBt) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(hLdacBt, "freed")) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(hLdacBt, "init")) { FUZZ_BAIL(); }

// priority must be -1 or +1
int pr = ((*FUZZ_PARAM(unsigned int) & 1u) ? 1 : -1);
int rc = ldacBT_alter_eqmid_priority(*hLdacBt, pr);
if (rc != 0) { FUZZ_BAIL(); }
// We cannot assert new eqmid value; just note that it may have changed

// Requires initialized handle and valid buffers
if (!hLdacBt) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(hLdacBt, "freed")) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(hLdacBt, "init")) { FUZZ_BAIL(); }

int mtu = FUZZ_GET_ATTR_INT(hLdacBt, "mtu");
int fmt = FUZZ_GET_ATTR_INT(hLdacBt, "fmt");
int channels = FUZZ_GET_ATTR_INT(hLdacBt, "channels");
if (mtu <= 0 || channels <= 0) { FUZZ_BAIL(); }

// Determine bytes per sample based on fmt
int bps = 0;
if (fmt == (int)LDACBT_SMPL_FMT_S16) bps = 2;
else if (fmt == (int)LDACBT_SMPL_FMT_S24) bps = 3;
else if (fmt == (int)LDACBT_SMPL_FMT_S32) bps = 4;
else if (fmt == (int)LDACBT_SMPL_FMT_F32) bps = 4;
else { FUZZ_BAIL(); }

// 128 samples per channel per call
int num_samples_per_ch = 128;
size_t pcm_bytes = (size_t)num_samples_per_ch * (size_t)channels * (size_t)bps;

// Prepare PCM buffer (interleaved). Fill with fuzz data then zero-pad as needed.
std::string fuzz = FUZZ_PARAM_STR();
std::string pcm;
pcm.resize(pcm_bytes, '\0');
for (size_t i = 0; i < pcm_bytes && i < fuzz.size(); ++i) { pcm[i] = fuzz[i]; }
// Output stream buffer: must be at least MTU bytes
if (mtu < 64) { mtu = 64; }
if (mtu > 1500) { mtu = 1500; }
std::string stream;
stream.resize((size_t)mtu, '\0');

int pcm_used = 0;
int stream_sz = 0;
int frame_num = 0;

// Randomly decide to provide PCM or to flush (NULL)
bool do_flush = ((*FUZZ_PARAM(unsigned int) & 1u) != 0);
void *p_pcm = do_flush ? (void*)0 : (void*)pcm.data();

int rc = ldacBT_encode(
    *hLdacBt,
    p_pcm,
    &pcm_used,
    reinterpret_cast<unsigned char*>(stream.data()),
    &stream_sz,
    &frame_num
);
if (rc != 0) { FUZZ_BAIL(); }
// Validate returned pointers and sizes are coherent
FUZZ_ASSERT(pcm_used >= 0, "pcm_used must be non-negative");
FUZZ_ASSERT(stream_sz >= 0, "stream size must be non-negative");
FUZZ_ASSERT(frame_num >= 0, "frame num must be non-negative");
if (stream_sz > 0) { FUZZ_ASSERT(stream_sz <= mtu, "Encoded output must not exceed MTU"); }

// Requires a valid (allocated) handle
if (!hLdacBt) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(hLdacBt, "freed")) { FUZZ_BAIL(); }

int err = ldacBT_get_error_code(*hLdacBt);
// No strict assertions; error code interpretation is library-specific
(void)err;

// Allocate a new ABR handle and wrap it
HANDLE_LDAC_ABR raw = ldac_ABR_get_handle();
if (!raw) { FUZZ_BAIL(); }
HANDLE_LDAC_ABR *hLdacAbr = new HANDLE_LDAC_ABR;
*hLdacAbr = raw;
FUZZ_SET_ATTR_INT(hLdacAbr, "freed", 0);
FUZZ_SET_ATTR_INT(hLdacAbr, "abr_init", 0);
// Default thresholds metadata
FUZZ_SET_ATTR_INT(hLdacAbr, "thCritical", 0);
FUZZ_SET_ATTR_INT(hLdacAbr, "thDangerousTrend", 0);
FUZZ_SET_ATTR_INT(hLdacAbr, "thSafety4HQSQ", 0);

// Validate handle
if (!hLdacAbr) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(hLdacAbr, "freed")) { FUZZ_BAIL(); }

ldac_ABR_free_handle(*hLdacAbr);
FUZZ_SET_ATTR_INT(hLdacAbr, "freed", 1);
// Drop from pool by not returning it

// Validate ABR handle
if (!hLdacAbr) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(hLdacAbr, "freed")) { FUZZ_BAIL(); }

// interval_ms must be within [1, 500]
unsigned int interval = (*FUZZ_PARAM(unsigned int) % 500u) + 1u;
int rc = ldac_ABR_Init(*hLdacAbr, interval);
if (rc != 0) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(hLdacAbr, "abr_init", 1);

// Validate ABR handle
if (!hLdacAbr) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(hLdacAbr, "freed")) { FUZZ_BAIL(); }

// Generate thresholds satisfying: thCritical >= thDangerousTrend >= thSafety4HQSQ, each > 0
unsigned int thSafety4HQSQ = (unsigned int)(*FUZZ_PARAM(unsigned int) % 50u) + 1u; // [1,50]
unsigned int thDangerousTrend = thSafety4HQSQ + (unsigned int)(*FUZZ_PARAM(unsigned int) % 51u); // [safety, safety+50]
unsigned int thCritical = thDangerousTrend + (unsigned int)(*FUZZ_PARAM(unsigned int) % 101u);   // [danger, danger+100]

int rc = ldac_ABR_set_thresholds(*hLdacAbr, thCritical, thDangerousTrend, thSafety4HQSQ);
if (rc != 0) { FUZZ_BAIL(); }

FUZZ_SET_ATTR_INT(hLdacAbr, "thCritical", (int)thCritical);
FUZZ_SET_ATTR_INT(hLdacAbr, "thDangerousTrend", (int)thDangerousTrend);
FUZZ_SET_ATTR_INT(hLdacAbr, "thSafety4HQSQ", (int)thSafety4HQSQ);

// Validate handles
if (!hLdacBt || !hLdacAbr) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(hLdacBt, "freed") || FUZZ_GET_ATTR_INT(hLdacAbr, "freed")) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(hLdacAbr, "abr_init")) { FUZZ_BAIL(); }

// TxQueueDepth: a non-negative packet count; choose a moderate range
unsigned int depth = (*FUZZ_PARAM(unsigned int) % 256u);
unsigned int enable = (*FUZZ_PARAM(unsigned int) & 1u) ? 1u : 0u;

int eq = ldac_ABR_Proc(*hLdacBt, *hLdacAbr, depth, enable);
// On success, returns updated EQMID (>=0). -1 indicates failure.
if (eq != -1) {
    FUZZ_ASSERT(eq >= 0, "ABR_Proc must return non-negative EQMID on success");
    // Track possible new EQMID on the encoder handle when ABR is enabled
    if (enable) { FUZZ_SET_ATTR_INT(hLdacBt, "eqmid", eq); }
}

// Construct a valid LDACBT_SMPL_FMT_T value (enum) and return as a managed pointer
// This type is user-managed; no API constructor exists. We ensure the value is one
// of the supported enum constants.
unsigned int choice = *FUZZ_PARAM(unsigned int) % 4u;
LDACBT_SMPL_FMT_T val = LDACBT_SMPL_FMT_S16;
if (choice == 0)      val = LDACBT_SMPL_FMT_S16;
else if (choice == 1) val = LDACBT_SMPL_FMT_S24;
else if (choice == 2) val = LDACBT_SMPL_FMT_S32;
else                  val = LDACBT_SMPL_FMT_F32;

LDACBT_SMPL_FMT_T *fmt = new(std::nothrow) LDACBT_SMPL_FMT_T;
if (!fmt) { FUZZ_BAIL(); }
*fmt = val;

// Attach a small bit of metadata for downstream checks (optional)
FUZZ_SET_ATTR_INT(fmt, "is_fmt", 1);
FUZZ_SET_ATTR_INT(fmt, "fmt_value", (int)val);

// Validation summary: outputs a non-null pointer with a value restricted to the documented enum set.
// No inputs or external resources are touched; no freeing is performed here (runtime will manage object lifetime).

