import struct
import random
import math
from typing import List, Tuple

# This generator produces valid-sized, interleaved PCM buffers expected by the ldacBT_encode fuzzer stub.
# The stub reads attributes (fmt, channels, mtu) from the handle and then calls FUZZ_PARAM_STR() to fill
# the PCM buffer of size: 128 samples per channel * channels * bytes_per_sample.
# We therefore generate a bytes payload that is composed of multiple candidate PCM frames for various
# common formats and channel counts. The fuzzer infra will pick from this buffer; by supplying rich, but
# valid content laid out as contiguous frames for different formats, we increase the chance the chosen
# slice matches the handle configuration while staying valid PCM.
#
# We include patterns:
# - Silence, DC offsets, max/min amplitude ramps
# - Sine waves at several frequencies
# - Stereo interleaving (L/R) and mono
# - For S24, ensure proper 3-byte little-endian packing
# - For F32, produce normalized floats in [-1, 1]
# Each sub-frame is exactly the expected size for that format/channel configuration.

SUPPORTED_FORMATS = [
    ("S16", 2),
    ("S24", 3),
    ("S32", 4),
    ("F32", 4),
]
CHANNEL_OPTIONS = [1, 2]  # mono and stereo are the most common for LDAC over BT
SAMPLES_PER_CH = 128
MAX_TOTAL_SIZE = 4096


def _gen_sine_table(n: int, freq: float, sample_rate: int) -> List[float]:
    # Generate n samples of a sine wave in [-1, 1]
    return [math.sin(2.0 * math.pi * freq * (i / sample_rate)) for i in range(n)]


def _clamp(x: int, lo: int, hi: int) -> int:
    return lo if x < lo else hi if x > hi else x


def _pack_s16_le(value: int) -> bytes:
    return struct.pack('<h', _clamp(value, -32768, 32767))


def _pack_s24_le(value: int) -> bytes:
    v = _clamp(value, -8388608, 8388607) & 0xFFFFFF
    # little-endian 24-bit: least significant byte first
    return bytes((v & 0xFF, (v >> 8) & 0xFF, (v >> 16) & 0xFF))


def _pack_s32_le(value: int) -> bytes:
    return struct.pack('<i', _clamp(value, -2147483648, 2147483647))


def _pack_f32_le(value: float) -> bytes:
    # Clamp to [-1, 1] to be a valid audio float
    v = max(-1.0, min(1.0, value))
    return struct.pack('<f', v)


def _gen_pcm_frame(fmt: str, bps: int, channels: int, content: str, sr: int, freq: float, seed: int) -> bytes:
    random.seed(seed)
    n = SAMPLES_PER_CH

    if fmt == "S16":
        peak = 32767
        pack = lambda x: _pack_s16_le(int(x))
    elif fmt == "S24":
        peak = 8388607
        pack = lambda x: _pack_s24_le(int(x))
    elif fmt == "S32":
        peak = 2147483647
        pack = lambda x: _pack_s32_le(int(x))
    elif fmt == "F32":
        peak = 1.0
        pack = lambda x: _pack_f32_le(float(x))
    else:
        return b""

    data = bytearray()

    if content == "silence":
        for i in range(n):
            for ch in range(channels):
                data += pack(0 if fmt != "F32" else 0.0)
        return bytes(data)

    if content == "dc":
        # DC offset differs per channel to test interleaving handling
        for i in range(n):
            for ch in range(channels):
                val = (peak * 0.25) * (1 if ch % 2 == 0 else -1)
                data += pack(val)
        return bytes(data)

    if content == "ramp":
        for i in range(n):
            t = i / max(1, (n - 1))
            base = (2.0 * t - 1.0)  # -1..1
            for ch in range(channels):
                if fmt == "F32":
                    val = base if ch == 0 else -base
                else:
                    val = (peak * base) if ch == 0 else (-peak * base)
                data += pack(val)
        return bytes(data)

    if content == "sine":
        # Generate different freq per channel for stereo
        table_L = _gen_sine_table(n, freq, sr)
        table_R = _gen_sine_table(n, freq * 1.5, sr)
        for i in range(n):
            for ch in range(channels):
                s = table_L[i] if ch == 0 else (table_R[i] if channels > 1 else table_L[i])
                if fmt == "F32":
                    val = 0.8 * s
                else:
                    val = int(0.8 * peak * s)
                data += pack(val)
        return bytes(data)

    if content == "noise":
        rng = random.Random(seed + 12345)
        for i in range(n):
            for ch in range(channels):
                if fmt == "F32":
                    val = (rng.random() * 2.0 - 1.0) * 0.7
                else:
                    val = int((rng.random() * 2.0 - 1.0) * 0.7 * peak)
                data += pack(val)
        return bytes(data)

    return bytes(data)


def _frame_size(bps: int, channels: int) -> int:
    return SAMPLES_PER_CH * channels * bps


def _pick_sample_rates(rng: random.Random) -> List[int]:
    # Common LDAC-supported sample rates
    srs = [44100, 48000, 88200, 96000]
    rng.shuffle(srs)
    return srs


def _pick_freqs(sr: int) -> List[float]:
    # A few representative audio frequencies (avoid too low/high extremes)
    base = [220.0, 440.0, 880.0, 1000.0, 1760.0]
    # Ensure below Nyquist
    return [f for f in base if f < sr / 2.5]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Plan: concatenate multiple complete frames for various (fmt, channels) pairs.
    # Keep total size under MAX_TOTAL_SIZE.
    patterns = ["silence", "dc", "ramp", "sine", "noise"]

    order_formats = SUPPORTED_FORMATS[:]
    rng.shuffle(order_formats)

    order_channels = CHANNEL_OPTIONS[:]
    rng.shuffle(order_channels)

    srs = _pick_sample_rates(rng)

    out = bytearray()

    # Compose frames until near the size limit
    for fmt, bps in order_formats:
        for ch in order_channels:
            # Add a few distinct content patterns per configuration
            rng.shuffle(patterns)
            # choose 2-3 patterns randomly
            num_patterns = 2 + rng.randint(0, 1)
            chosen = patterns[:num_patterns]

            # select a sample rate and potential frequency list
            sr = srs[0]
            freqs = _pick_freqs(sr)
            if not freqs:
                freqs = [440.0]

            for content in chosen:
                if content == "sine":
                    freq = rng.choice(freqs)
                else:
                    freq = 0.0
                frame = _gen_pcm_frame(fmt, bps, ch, content, sr, freq, seed ^ (hash((fmt, ch, content)) & 0xFFFFFFFF))
                # Ensure we do not exceed MAX_TOTAL_SIZE
                if len(out) + len(frame) > MAX_TOTAL_SIZE:
                    return bytes(out)
                out += frame

    return bytes(out)
